pragma solidity 0.8.20;

import "./Context.sol";

abstract contract Ownable is Context {
    address private _owner;

    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);

    constructor () {
        address msgSender = _msgSender();
        _owner = msgSender;
        emit OwnershipTransferred(address(0), msgSender);
    }

    function owner() public view returns (address) {
        return _owner;
    }

    modifier onlyOwner() {
        require(_owner == _msgSender(), "Ownable: caller is not the owner");
        _;
    }

    function transferOwnership(address newOwner) public virtual onlyOwner {
        require(newOwner != address(0), "Ownable: new owner is the zero address");
        emit OwnershipTransferred(_owner, newOwner);
        _owner = newOwner;
    }
}"},"SwapLibrary.sol":{"content":"// SPDX-License-Identifier: UNLICENSED

pragma solidity 0.8.20;

import "./IFactory.sol";
import "./IPair.sol";

library SwapLibrary {
    // returns sorted token addresses, used to handle return values from pairs sorted in this order
    function sortTokens(address tokenA, address tokenB) internal pure returns(address token0, address token1) {
        require(tokenA != tokenB, 'SwapLibrary Token: IDENTICAL_ADDRESSES');
        (token0, token1) = tokenA < tokenB ? (tokenA, tokenB) : (tokenB, tokenA);
        require(token0 != address(0), 'SwapLibrary Token: ZERO_ADDRESS');
    }

    function pairFor(address factory, address tokenA, address tokenB) internal view returns(address pair) {
        pair = IFactory(factory).getPair(tokenA, tokenB);
        require(pair != address(0), 'SwapLibrary Token: pairFor called on not yet created pair');
        return pair;
    }

    // fetches and sorts the reserves for a pair
    function getReserves(address pair, address tokenA, address tokenB) internal view returns(uint256 reserveA, uint256 reserveB) {
        (address token0,) = sortTokens(tokenA, tokenB);
        (uint256 reserve0, uint256 reserve1,) = IPair(pair).getReserves();
        (reserveA, reserveB) = tokenA == token0 ? (reserve0, reserve1) : (reserve1, reserve0);
    }

    // given an input amount of an asset and pair reserves, returns the maximum output amount of the other asset
    function getAmountOut(uint256 amountIn, uint256 reserveIn, uint256 reserveOut) internal pure returns(uint256 amountOut) {
        require(amountIn > 0, 'SwapLibrary Token: INSUFFICIENT_INPUT_AMOUNT');
        require(reserveIn > 0 && reserveOut > 0, 'SwapLibrary Token: INSUFFICIENT_LIQUIDITY');
        uint256 amountInWithFee = amountIn * 997;
        uint256 numerator = amountInWithFee * reserveOut;
        uint256 denominator = (reserveIn * 1000) + amountInWithFee;
        amountOut = numerator / denominator;
    }
}"},"Token.sol":{"content":"// SPDX-License-Identifier: MIT

pragma solidity 0.8.20;

import "./ITRC20.sol"; // Interface for the TRC20 token standard
import "./SwapLibrary.sol";
import "./Ownable.sol";

contract EcoDoge is ITRC20, Ownable {

    // Define a struct to hold balance and allowance data
    struct AccountData {
        uint256 balance;
        mapping(address => uint256) allowances;
    }

    // Single mapping to hold all account data
    mapping(address => AccountData) private _accounts;

    // Mapping to hold pair addresses
    mapping(address => bool) public isPair;

    // Mapping to track addresses excluded from fees
    mapping(address => bool) public excludedFromFee;

    // Total supply of the token
    uint256 private immutable _totalSupply;
    uint256 private _totalBurned;

    // Token details: name, symbol, and decimals
    string private _name;
    string private _symbol;
    uint8 private immutable _decimals;

    uint256 public buyFee = 5; // 5 is 5.0%
    uint256 public sellFee = 5; // 5 is 5.0%
    uint256 public minAmountForAutoSwap; // Minimum amount of tokens to be transfered for the fee to be auto swapped
    uint256 public launchTimestamp;

    bool private inFeeSwap;
    bool public feeEnabled;
    bool public autoSwapEnabled;
    bool public swapAllTokenBalance;

    address private WETH;
    address public dexPair;
    address public dexPair2;
    address public feeWallet;


    event FeeEnabledUpdated(bool enabled);
    event AutoSwapUpdated(bool enabled);
    event SellFeeUpdated(uint256 fee);
    event BuyFeeUpdated(uint256 fee);
    event AddedNewPair(address pair, address factory);
    event AddedNewDex(address pair, address factory);
    event ExcludedFromFee(address account, bool isExcluded);
    event FeeTransferFailed(uint256 ethAmount, address recipient);
    event FeeConvertedToWETH(uint256 tokenAmount, uint256 ethReceived, address recipient);
    event MinAmountForAutoSwapUpdated(uint256 amount);
    event Burned(address account, uint256 amount);

    // Fallback function to receive ETH from swaps
    receive() external payable {}

    // Constructor that initializes the token with a name, symbol, decimals, and initial supply
    constructor (string memory tokenName, string memory tokenSymbol, uint8 tokenDecimals, address _WETH, address _factoryJM, address _factory2, uint256 _launchTimestamp) payable {
        _name = tokenName; // Set the token name
        _symbol = tokenSymbol; // Set the token symbol
        _decimals = tokenDecimals; // Set the number of decimals for the token
        feeWallet = msg.sender;
        WETH = _WETH;
        dexPair = IFactory(_factoryJM).createPair(address(this), _WETH);
        dexPair2 = IFactory(_factory2).createPair(address(this), _WETH);
        require(dexPair != address(0), "Pair does not exist");
        require(dexPair2 != address(0), "Pair does not exist");
        isPair[dexPair] = true;
        isPair[dexPair2] = true;
        emit AddedNewDex(dexPair, _factoryJM);
        emit AddedNewDex(dexPair2, _factory2);
        uint256 amount = 10_000_000_000 * (10 ** tokenDecimals); // Calculate the initial supply
        _totalSupply = amount; // Set the total supply
        _accounts[msg.sender].balance = amount; // Assign the initial supply to the contract creator
        emit Transfer(address(0), msg.sender, amount); // Emit a transfer event for minting
        launchTimestamp = _launchTimestamp; // Set the token launch period
    }

    // Returns the name of the token
    function name() public view returns (string memory) {
        return _name;
    }

    // Returns the symbol of the token
    function symbol() public view returns (string memory) {
        return _symbol;
    }

    // Returns the number of decimals used to get its user representation
    function decimals() public view returns (uint8) {
        return _decimals;
    }

    // Returns the total supply of the token
    function totalSupply() public view returns (uint256) {
        return (_totalSupply - _totalBurned);
    }

    // Returns the total burned supply of the token
    function totalBurned() public view returns (uint256) {
        return _totalBurned;
    }

    // Returns the balance of a specific address
    function balanceOf(address account) public view returns (uint256) {
        return _accounts[account].balance;
    }

    // Transfers tokens from the caller to a recipient
    function transfer(address recipient, uint256 amount) public returns (bool) {
        _transfer(msg.sender, recipient, amount); // Internal transfer function is called
        return true; // Return true if the transfer was successful
    }

    // Returns the remaining number of tokens that `spender` can spend on behalf of `owner`
    function allowance(address owner, address spender) public view returns (uint256) {
        return _accounts[owner].allowances[spender];
    }

    // Approves the `spender` to transfer up to `value` amount of tokens on behalf of the caller
    function approve(address spender, uint256 value) public returns (bool) {
        _approve(msg.sender, spender, 0); // Automatically set the current allowance to zero before setting the new value
        _approve(msg.sender, spender, value); // Now set the new allowance
        return true; // Return true if the approval was successful
    }

    // Transfers tokens on behalf of an owner, if the caller has sufficient allowance
    function transferFrom(address sender, address recipient, uint256 amount) public returns (bool) {
        uint256 currentAllowance = _accounts[sender].allowances[msg.sender]; // Cache the allowance in memory
        require(currentAllowance > amount || currentAllowance == amount, "Amount exceeds allowance"); // Check the allowance

        _transfer(sender, recipient, amount); // Internal transfer function is called

        // Update the allowance if it's not set to the maximum possible value
        if (currentAllowance != type(uint256).max) {
            _approve(sender, msg.sender, currentAllowance - amount);
        }

        return true; // Return true if the transfer was successful
    }

    // Increases the allowance of `spender` by `addedValue`
    function increaseAllowance(address spender, uint256 addedValue) public returns (bool) {
        // Cache the current allowance in memory
        uint256 currentAllowance = _accounts[msg.sender].allowances[spender];

        // Update the allowance in memory
        uint256 newAllowance = currentAllowance + addedValue;

        // Call the internal _approve function to update the allowance in storage
        _approve(msg.sender, spender, newAllowance);

        // Emit the Approval event
        emit Approval(msg.sender, spender, newAllowance);

        return true;
    }

    // Decreases the allowance of `spender` by `subtractedValue`
    function decreaseAllowance(address spender, uint256 subtractedValue) public returns (bool) {
        // Cache the current allowance in memory
        uint256 currentAllowance = _accounts[msg.sender].allowances[spender];

        // Ensure the new allowance does not underflow
        require(currentAllowance > subtractedValue || currentAllowance == subtractedValue, "Decreased allowance below 0");

        // Calculate the new allowance in memory
        uint256 newAllowance = currentAllowance - subtractedValue;

        // Call the internal _approve function to update the allowance in storage
        _approve(msg.sender, spender, newAllowance);

        // Emit the Approval event
        emit Approval(msg.sender, spender, newAllowance);

        return true;
    }

    // Internal function to handle token transfers
    function _transfer(address sender, address recipient, uint256 amount) private {
        require(sender != address(0), "Transfer from the zero address");
        require(recipient != address(0), "Transfer to the zero address");
        require(amount > 0, "Amount must be greater than 0");

        // Restrict transfers to only the owner before the restriction period ends
        if (block.timestamp < launchTimestamp) {
            require(sender == owner() || recipient == owner() || recipient == dexPair || recipient == dexPair2, "Transfers restricted to owner and adding liquidity");
        }

        // Skip fee logic for excluded addresses or during fee swaps
        if (excludedFromFee[sender] || excludedFromFee[recipient] || inFeeSwap || !feeEnabled) {
            _basicTransfer(sender, recipient, amount);
            return;
        }

        uint256 transferAmount = amount; // Default transfer amount
        uint256 feeAmount = 0; // Initialize fee amount

        // Check if the transfer involves a buy or sell and fees are enabled
        if (feeEnabled && (isPair[recipient] || isPair[sender])) {
            // Determine fee percentage
            uint256 feePercent = isPair[recipient] ? sellFee : buyFee;

            // Calculate fee amount
            feeAmount = (amount * feePercent) / 100; // Calculate the fee for the transfer

            // Reduce transfer amount by the fee
            transferAmount = amount - feeAmount;

            // Deduct fee from sender's balance
            _accounts[sender].balance -= feeAmount;

            // Add fee to contract's balance for swapping later
            _accounts[address(this)].balance += feeAmount;
        }

        // Perform the user's transfer
        _basicTransfer(sender, recipient, transferAmount);

        // Swap fee tokens for ETH and send to fee wallet
        if (autoSwapEnabled && feeAmount > 0 && minAmountForAutoSwap <= amount) {
            inFeeSwap = true;
            _swapTokensForWETH(feeAmount, sender, recipient);
            inFeeSwap = false;
        }
    }

    // Basic transfer function without fee logic
    function _basicTransfer(address sender, address recipient, uint256 amount) private {
        AccountData storage senderAccount = _accounts[sender];
        AccountData storage recipientAccount = _accounts[recipient];

        uint256 senderBalance = senderAccount.balance;
        require(senderBalance >= amount, "Amount exceeds balance");

        unchecked {
            senderAccount.balance = senderBalance - amount;
            recipientAccount.balance += amount;
        }

        emit Transfer(sender, recipient, amount);
    }

    // Internal function to approve a spender to spend a certain amount of tokens
    function _approve(address owner, address spender, uint256 value) private {
        require(owner != address(0), "Approve from the zero address");
        require(spender != address(0), "Approve to the zero address");

        // Cache the owner's account data in memory to minimize SLOAD operations
        AccountData storage ownerAccount = _accounts[owner];

        uint256 currentAllowance = ownerAccount.allowances[spender];

        // Only update the allowance if it's different from the current one
        if (currentAllowance != value) {
            ownerAccount.allowances[spender] = value; // Update the stored allowance
            emit Approval(owner, spender, value); // Emit the Approval event
        }
    }

    function _swapTokensForWETH(uint256 tokenAmount, address sender, address recipient) private {
        tokenAmount = swapAllTokenBalance == true ? _accounts[address(this)].balance : tokenAmount;
        if(tokenAmount > 0) {
            address useDEX = (sender == dexPair || recipient == dexPair) ? dexPair2 : dexPair;

            // Get token reserves from the pair
            (uint256 reserveToken, uint256 reserveWETH) = SwapLibrary.getReserves(useDEX, address(this), WETH);
            require(reserveToken > 0 && reserveWETH > 0, "Invalid reserves");

            // Calculate the amount of ETH to receive
            uint256 amountOut = SwapLibrary.getAmountOut(tokenAmount, reserveToken, reserveWETH);
            require(amountOut > 0, "Insufficient output amount");

            // Directly update balances for the pair
            _accounts[address(this)].balance -= tokenAmount; // Deduct tokens from contract
            _accounts[useDEX].balance += tokenAmount; // Add tokens to the pair

            emit Transfer(address(this), useDEX, tokenAmount);

            // Perform the swap
            (address token0, ) = SwapLibrary.sortTokens(address(this), WETH);
            if (token0 == address(this)) {
                IPair(useDEX).swap(0, amountOut, feeWallet, new bytes(0));
            } else {
                IPair(useDEX).swap(amountOut, 0, feeWallet, new bytes(0));
            }

            emit FeeConvertedToWETH(tokenAmount, amountOut, feeWallet);
        }
    }

    function burn(uint256 amount) public {
        _burn(_msgSender(), amount);
    }

    function _burn(address account, uint256 amount) internal {
        require(account != address(0), "Can not burn from the zero address");

        uint256 accountBalance = _accounts[account].balance;
        require(accountBalance >= amount, "Burn exceeds available amount");
        unchecked { _accounts[account].balance = accountBalance - amount; }
        _totalBurned += amount;

        emit Transfer(account, address(0), amount);
        emit Burned(account, amount);
    }

    function setDex(address _factory) external onlyOwner {
        dexPair = SwapLibrary.pairFor(_factory, address(this), WETH);
        require(dexPair != address(0), "Pair does not exist");
        require(dexPair != dexPair2, "Can not be the same as dexPair2");

        excludedFromFee[dexPair] = false;
        emit AddedNewDex(dexPair, _factory);
    }

    function setDex2(address _factory) external onlyOwner {
        dexPair2 = SwapLibrary.pairFor(_factory, address(this), WETH);
        require(dexPair2 != address(0), "Pair does not exist");
        require(dexPair2 != dexPair, "Can not be the same as dexPair");

        excludedFromFee[dexPair2] = false;
        emit AddedNewDex(dexPair2, _factory);
    }

    function addPair(address _tokenB, address _factory) external onlyOwner returns (address pair) {
        pair = SwapLibrary.pairFor(_factory, address(this), _tokenB);
        require(pair != address(0), "Pair does not exist");

        isPair[pair] = true;
        excludedFromFee[pair] = false;
        emit AddedNewPair(pair, _factory);
    }

    function setFeeEnabled(bool _enabled) external onlyOwner {
        feeEnabled = _enabled;
        emit FeeEnabledUpdated(_enabled);
    }

    function setAutoSwap(bool _enabled) external onlyOwner {
        autoSwapEnabled = _enabled;
        emit AutoSwapUpdated(_enabled);
    }

    function setSwapAllTokenBalance(bool _enabled) external onlyOwner {
        swapAllTokenBalance = _enabled;
    }

    function setSellFee(uint256 _feePercent) external onlyOwner {
        require(_feePercent <= 25, "Can not be bigger fee than 25%");

        sellFee = _feePercent;
        emit SellFeeUpdated(_feePercent);
    }

    function setBuyFee(uint256 _feePercent) external onlyOwner {
        require(_feePercent <= 25, "Can not be bigger fee than 25%");

        buyFee = _feePercent;
        emit BuyFeeUpdated(_feePercent);
    }

    function setFeeWallet(address _feeWallet) external onlyOwner {
        require(_feeWallet != address(0), "Fee wallet cannot be the zero address");
        require(!isContract(_feeWallet), "Fee wallet cannot be a contract");

        feeWallet = _feeWallet;
    }

    function setMinAmountForAutoSwap(uint256 _amount) external onlyOwner {
        minAmountForAutoSwap = _amount;
        emit MinAmountForAutoSwapUpdated(_amount);
    }

    // Function to update the fee exclusion list
    function setExcludedFromFee(address account, bool excluded) external onlyOwner {
        require(account != address(0), "Can not exclude the zero address");
        require(account != dexPair, "The DEX can not be excluded from fee");
        require(!isPair[account], "Can not exclude a pair address");

        excludedFromFee[account] = excluded;

        emit ExcludedFromFee(account, excluded);
    }

    // Function to update the launch timestamp
    function setLaunchTimestamp(uint256 _launchTimestamp) external onlyOwner {
        require(block.timestamp < launchTimestamp, "Token already launched");
        require(_launchTimestamp > block.timestamp, "Need to set a launch time in the future");

        launchTimestamp = _launchTimestamp;
    }

    function isContract(address account) internal view returns (bool) {
        uint256 size;
        assembly {
            size := extcodesize(account)
        }
        return size > 0;
    }

    // Function to withdraw tokens that get sent to the contract (by airdrop or by accident)
    function withdrawERC20token(address _token, uint256 amount, address payable recipient) external onlyOwner {
        require(recipient != address(0), "Cannot withdraw to the zero address");

        uint256 bal = ITRC20(_token).balanceOf(address(this));
        require(bal >= amount, "Not enough tokens in the contract");

        ITRC20(_token).transfer(recipient, amount);
    }

    function withdrawETH(address payable recipient) external onlyOwner {
        require(recipient != address(0), "Recipient cannot be the zero address");
        uint256 contractBalance = address(this).balance;
        require(contractBalance > 0, "No ETH balance to withdraw");

        (bool success, ) = recipient.call{value: contractBalance}("");
        require(success, "ETH transfer failed");
    }
}"}}
